    self.sidebar
        .as_ref()
        .map_or(false, |s| s.is_threads_list_view_active(cx))
}

pub fn multi_workspace_enabled(&self, cx: &App) -> bool {
    !DisableAiSettings::get_global(cx).disable_ai && AgentSettings::get_global(cx).enabled
}

